discrete ConfigurationManagementSystem
port:
    event input real CONFIGURE;
    event input real RECONFIGURE;
    event input real RESET;
    event output real CONFIG_DONE;
state:
    initial state WaitForConfigSignal
        when entry() then
            statehold(1);
        end;
        when receive(CONFIGURE) then
            transition(LoadingConfigData);
        end;
    end;

    state LoadingConfigData
        when entry() then
            statehold(1);
        end;
        when receive(CONFIGURE) then
            transition(ConfigSuccess);
            out
                send(CONFIG_DONE, 1);
        end;
        when timeover() then
            transition(WaitForConfigSignal);
        end;
    end;

    state ConfigSuccess
        when entry() then
            statehold(1);
        end;
        when receive(RECONFIGURE) then
            transition(WaitForConfigSignal);
        end;
        when receive(RESET) then
            transition(WaitForConfigSignal);
        end;
    end;
end;
end;

discrete LogicFunctionModule
port:
    event input real CONFIG_DONE;
    event input real STOP;
    event input real START;
    event input real RESET;
    event output real FUNCTION_RUNNING;
state:
    initial state WaitForConfigComplete
        when entry() then
            statehold(1);
        end;
        when receive(CONFIG_DONE) then
            transition(ExecuteLogicFunction);
        end;
    end;

    state ExecuteLogicFunction
        when entry() then
            statehold(1);
        end;
        when receive(STOP) then
            transition(Pause);
            out
                send(FUNCTION_RUNNING, 1);
        end;
    end;

    state Pause
        when entry() then
            statehold(1);
        end;
        when receive(START) then
            transition(ExecuteLogicFunction);
        end;
        when receive(RESET) then
            transition(WaitForConfigComplete);
        end;
    end;
end;
end;

discrete ClockManagementModule
port:
    event input real CLOCK_ENABLE;
    event input real CLOCK_DISABLE;
    event input real RESET;
    event output real CLOCK_DISTRIBUTED;
state:
    initial state WaitForClockSignal
        when entry() then
            statehold(1);
        end;
        when receive(CLOCK_ENABLE) then
            transition(DistributeClockSignal);
        end;
    end;

    state DistributeClockSignal
        when entry() then
            statehold(1);
        end;
        when receive(CLOCK_DISABLE) then
            transition(WaitForClockSignal);
        end;
        when receive(RESET) then
            transition(WaitForClockSignal);
            out
                send(CLOCK_DISTRIBUTED, 1);
        end;
    end;
end;
end;

